#!/usr/bin/env node
// scripts/regenerate-install-scripts.mjs
//
// Single source of truth for ALL packs' install.sh files.
//
// Reads:
//   scripts/install-template.sh             (canonical multi-agent installer)
//   scripts/install-template-deprecated.sh  (alias redirect stub)
//   web/public/packs/<slug>/manifest.json   (to detect deprecated_alias_of)
//
// Writes:
//   web/public/packs/<slug>/install.sh      (substituted for every pack)
//
// Why this script: prior install.sh files were generated by THREE different
// emitters (generate-packs.mjs node template, sync-spellbook-packs.py f-string,
// and hand-written ones). The f-string emitter was broken (line 435 NameError
// on INSTALL_DEST + line 434 double-curly literal leaked into 4 deprecated
// install.sh files, causing `bad substitution` at runtime). This script
// collapses them into one canonical template + sed-style substitution.
//
// Usage:
//   node scripts/regenerate-install-scripts.mjs           # write all
//   node scripts/regenerate-install-scripts.mjs --dry-run # preview only
//   node scripts/regenerate-install-scripts.mjs --pack frontend-engineer

import { readFileSync, writeFileSync, readdirSync, existsSync, statSync, chmodSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..');
const PACKS_DIR = join(ROOT, 'web', 'public', 'packs');
const TEMPLATE = join(__dirname, 'install-template.sh');
const TEMPLATE_DEPR = join(__dirname, 'install-template-deprecated.sh');

const args = process.argv.slice(2);
const DRY_RUN = args.includes('--dry-run');
const PACK_FILTER = (() => {
  const i = args.indexOf('--pack');
  if (i >= 0 && i + 1 < args.length) return args[i + 1];
  return null;
})();

function loadTemplate(path) {
  if (!existsSync(path)) {
    console.error(`ERROR: template missing: ${path}`);
    process.exit(1);
  }
  return readFileSync(path, 'utf-8');
}

function loadManifest(packDir) {
  const path = join(packDir, 'manifest.json');
  if (!existsSync(path)) return null;
  try {
    return JSON.parse(readFileSync(path, 'utf-8'));
  } catch (err) {
    console.error(`ERROR: invalid manifest.json at ${path}: ${err.message}`);
    return null;
  }
}

function renderCanonical(template, packId) {
  return template.replace(/__PACK_ID__/g, packId);
}

function renderDeprecated(template, loserId, winnerId) {
  return template
    .replace(/__LOSER_ID__/g, loserId)
    .replace(/__WINNER_ID__/g, winnerId);
}

function main() {
  const canonicalTemplate = loadTemplate(TEMPLATE);
  const deprecatedTemplate = loadTemplate(TEMPLATE_DEPR);

  const packs = readdirSync(PACKS_DIR)
    .filter(name => statSync(join(PACKS_DIR, name)).isDirectory())
    .filter(name => !PACK_FILTER || name === PACK_FILTER)
    .sort();

  if (packs.length === 0) {
    console.error(`ERROR: no packs found under ${PACKS_DIR}` +
      (PACK_FILTER ? ` (filter: ${PACK_FILTER})` : ''));
    process.exit(1);
  }

  let writtenCanonical = 0;
  let writtenDeprecated = 0;
  let skipped = 0;

  for (const slug of packs) {
    const packDir = join(PACKS_DIR, slug);
    const manifest = loadManifest(packDir);
    if (!manifest) {
      console.warn(`SKIP ${slug}: no/invalid manifest.json`);
      skipped++;
      continue;
    }

    const installPath = join(packDir, 'install.sh');
    let rendered;
    let kind;

    if (manifest.deprecated_alias_of) {
      rendered = renderDeprecated(deprecatedTemplate, slug, manifest.deprecated_alias_of);
      kind = 'deprecated';
    } else {
      rendered = renderCanonical(canonicalTemplate, slug);
      kind = 'canonical';
    }

    if (DRY_RUN) {
      console.log(`DRY ${slug.padEnd(35)} ${kind.padEnd(10)} ${rendered.length}b`);
    } else {
      writeFileSync(installPath, rendered, 'utf-8');
      chmodSync(installPath, 0o755);
      console.log(`OK  ${slug.padEnd(35)} ${kind.padEnd(10)} ${rendered.length}b`);
    }
    if (kind === 'canonical') writtenCanonical++;
    else writtenDeprecated++;
  }

  console.log('');
  console.log(`Summary: canonical=${writtenCanonical}  deprecated=${writtenDeprecated}  skipped=${skipped}  total=${packs.length}`);
  console.log(DRY_RUN ? '(dry-run, no writes)' : 'wrote install.sh for every pack');
}

main();
